<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany};
final class Claim extends Model{use HasUuids;protected$fillable=['tenant_id','policy_id','claimant_party_id','claim_number','status','loss_occurred_at','loss_details','loss_location','estimated_loss_minor','currency','submitted_at','acknowledged_at','closed_at','carrier_reference','assigned_to','priority','current_reserve_minor','approved_amount_minor','version','reopened_at','reopened_by','closure_summary'];protected function casts():array{return['loss_occurred_at'=>'datetime','loss_details'=>'array','submitted_at'=>'datetime','acknowledged_at'=>'datetime','closed_at'=>'datetime','reopened_at'=>'datetime'];}public function policy():BelongsTo{return$this->belongsTo(Policy::class);}public function claimant():BelongsTo{return$this->belongsTo(Party::class,'claimant_party_id');}public function assignee():BelongsTo{return$this->belongsTo(User::class,'assigned_to');}public function reserves():HasMany{return$this->hasMany(ClaimReserveChange::class);}public function decisions():HasMany{return$this->hasMany(ClaimDecision::class);}public function payments():HasMany{return$this->hasMany(ClaimPayment::class);}public function disputes():HasMany{return$this->hasMany(ClaimDispute::class);}public function recoveries():HasMany{return$this->hasMany(ClaimRecovery::class);}}
